begin;

create type public.cost_center_type as enum('program','horse','facility','department','corporate');

create table public.cost_centers(
 id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete restrict,
 code text not null,name text not null,center_type public.cost_center_type not null,linked_horse_id uuid references public.horses(id) on delete restrict,
 active boolean not null default true,description text,created_by uuid not null references auth.users(id) on delete restrict,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 constraint cost_center_code check(code~'^[A-Z0-9][A-Z0-9_-]{1,19}$'),constraint cost_center_name check(char_length(btrim(name)) between 2 and 120),
 constraint cost_center_description check(description is null or char_length(btrim(description)) between 2 and 300),
 constraint cost_center_horse_scope check((center_type='horse' and linked_horse_id is not null)or(center_type<>'horse' and linked_horse_id is null)),unique(academy_id,code),unique(academy_id,linked_horse_id)
);
create index cost_centers_academy_active_idx on public.cost_centers(academy_id,active,center_type,code);create index cost_centers_created_by_idx on public.cost_centers(created_by);

create table public.cost_center_allocation_rules(
 id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete restrict,
 account_id uuid not null references public.gl_accounts(id) on delete restrict,cost_center_id uuid not null references public.cost_centers(id) on delete restrict,
 allocation_bps integer not null check(allocation_bps between 1 and 10000),effective_from date not null,effective_to date,
 note text,created_by uuid not null references auth.users(id) on delete restrict,updated_by uuid not null references auth.users(id) on delete restrict,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 constraint cost_center_rule_dates check(effective_to is null or effective_to>=effective_from),constraint cost_center_rule_note check(note is null or char_length(btrim(note)) between 2 and 240),
 unique(account_id,cost_center_id,effective_from)
);
create index cost_center_rules_academy_account_idx on public.cost_center_allocation_rules(academy_id,account_id,effective_from,effective_to);create index cost_center_rules_center_idx on public.cost_center_allocation_rules(cost_center_id);create index cost_center_rules_created_by_idx on public.cost_center_allocation_rules(created_by);create index cost_center_rules_updated_by_idx on public.cost_center_allocation_rules(updated_by);

create table public.cost_center_allocations(
 id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete restrict,
 journal_entry_id uuid not null references public.gl_journal_entries(id) on delete restrict,journal_line_id uuid not null references public.gl_journal_lines(id) on delete restrict,
 account_id uuid not null references public.gl_accounts(id) on delete restrict,cost_center_id uuid not null references public.cost_centers(id) on delete restrict,
 rule_id uuid not null references public.cost_center_allocation_rules(id) on delete restrict,entry_date date not null,currency text not null check(currency~'^[A-Z]{3}$'),
 source_amount_minor bigint not null,allocated_minor bigint not null,allocation_bps integer not null check(allocation_bps between 1 and 10000),allocated_at timestamptz not null default now(),
 unique(journal_line_id,cost_center_id)
);
create index cost_center_allocations_center_date_idx on public.cost_center_allocations(academy_id,cost_center_id,currency,entry_date);create index cost_center_allocations_entry_idx on public.cost_center_allocations(journal_entry_id);create index cost_center_allocations_account_idx on public.cost_center_allocations(account_id);create index cost_center_allocations_rule_idx on public.cost_center_allocations(rule_id);

create table public.cost_center_monthly_budgets(
 id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete restrict,cost_center_id uuid not null references public.cost_centers(id) on delete restrict,
 month_start date not null check(extract(day from month_start)=1),currency text not null check(currency~'^[A-Z]{3}$'),revenue_budget_minor bigint not null default 0 check(revenue_budget_minor>=0),expense_budget_minor bigint not null default 0 check(expense_budget_minor>=0),
 note text,created_by uuid not null references auth.users(id) on delete restrict,updated_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 constraint cost_center_budget_note check(note is null or char_length(btrim(note)) between 2 and 240),unique(cost_center_id,month_start,currency)
);
create index cost_center_budgets_academy_month_idx on public.cost_center_monthly_budgets(academy_id,currency,month_start);create index cost_center_budgets_created_by_idx on public.cost_center_monthly_budgets(created_by);create index cost_center_budgets_updated_by_idx on public.cost_center_monthly_budgets(updated_by);

alter table public.purchase_orders add column cost_center_id uuid references public.cost_centers(id) on delete restrict;
create index purchase_orders_cost_center_idx on public.purchase_orders(cost_center_id,status,expected_on) where cost_center_id is not null;

alter table public.cost_centers enable row level security;alter table public.cost_center_allocation_rules enable row level security;alter table public.cost_center_allocations enable row level security;alter table public.cost_center_monthly_budgets enable row level security;
revoke all on public.cost_centers,public.cost_center_allocation_rules,public.cost_center_allocations,public.cost_center_monthly_budgets from public,anon,authenticated;
grant select,insert,update on public.cost_centers,public.cost_center_allocation_rules,public.cost_center_monthly_budgets to authenticated;grant select,insert,update,delete on public.cost_center_allocations to authenticated;
grant select,insert,update,delete on public.cost_centers,public.cost_center_allocation_rules,public.cost_center_allocations,public.cost_center_monthly_budgets to service_role;grant usage on type public.cost_center_type to authenticated;

create policy cost_centers_read_administrators on public.cost_centers for select to authenticated using((select private.is_platform_administrator()));create policy cost_centers_insert_administrators on public.cost_centers for insert to authenticated with check((select private.is_platform_administrator())and created_by=(select auth.uid()));create policy cost_centers_update_administrators on public.cost_centers for update to authenticated using((select private.is_platform_administrator()))with check((select private.is_platform_administrator()));
create policy cost_center_rules_read_administrators on public.cost_center_allocation_rules for select to authenticated using((select private.is_platform_administrator()));create policy cost_center_rules_insert_administrators on public.cost_center_allocation_rules for insert to authenticated with check((select private.is_platform_administrator())and created_by=(select auth.uid())and updated_by=(select auth.uid()));create policy cost_center_rules_update_administrators on public.cost_center_allocation_rules for update to authenticated using((select private.is_platform_administrator()))with check((select private.is_platform_administrator())and updated_by=(select auth.uid()));
create policy cost_center_allocations_read_administrators on public.cost_center_allocations for select to authenticated using((select private.is_platform_administrator()));create policy cost_center_allocations_insert_administrators on public.cost_center_allocations for insert to authenticated with check((select private.is_platform_administrator()));create policy cost_center_allocations_update_administrators on public.cost_center_allocations for update to authenticated using((select private.is_platform_administrator()))with check((select private.is_platform_administrator()));create policy cost_center_allocations_delete_administrators on public.cost_center_allocations for delete to authenticated using((select private.is_platform_administrator()));
create policy cost_center_budgets_read_administrators on public.cost_center_monthly_budgets for select to authenticated using((select private.is_platform_administrator()));create policy cost_center_budgets_insert_administrators on public.cost_center_monthly_budgets for insert to authenticated with check((select private.is_platform_administrator())and created_by=(select auth.uid())and updated_by=(select auth.uid()));create policy cost_center_budgets_update_administrators on public.cost_center_monthly_budgets for update to authenticated using((select private.is_platform_administrator()))with check((select private.is_platform_administrator())and updated_by=(select auth.uid()));

create function private.validate_cost_center_scope() returns trigger language plpgsql set search_path='' as $$
begin
 if new.linked_horse_id is not null and not exists(select 1 from public.horses where id=new.linked_horse_id and academy_id=new.academy_id) then raise exception 'linked horse must belong to academy' using errcode='23514';end if;new.updated_at:=now();return new;
end;$$;create trigger validate_cost_center_scope before insert or update on public.cost_centers for each row execute function private.validate_cost_center_scope();

create function private.refresh_cost_center_entry(target_entry_id uuid) returns integer language plpgsql security invoker set search_path='' as $$
declare scoped_entry public.gl_journal_entries%rowtype;source record;rule record;inserted integer:=0;source_amount bigint;
begin
 select * into scoped_entry from public.gl_journal_entries where id=target_entry_id;if not found or scoped_entry.status not in('posted','reversed') then return 0;end if;
 delete from public.cost_center_allocations allocation where allocation.journal_entry_id=scoped_entry.id;
 for source in select line.id line_id,line.account_id,account.category,account.normal_balance,line.debit_minor,line.credit_minor from public.gl_journal_lines line join public.gl_accounts account on account.id=line.account_id where line.journal_entry_id=scoped_entry.id and account.category in('revenue','expense') loop
  source_amount:=case when source.normal_balance='debit' then source.debit_minor-source.credit_minor else source.credit_minor-source.debit_minor end;
  for rule in select allocation_rule.id,allocation_rule.cost_center_id,allocation_rule.allocation_bps from public.cost_center_allocation_rules allocation_rule join public.cost_centers center on center.id=allocation_rule.cost_center_id where allocation_rule.account_id=source.account_id and allocation_rule.academy_id=scoped_entry.academy_id and center.active and allocation_rule.effective_from<=scoped_entry.entry_date and (allocation_rule.effective_to is null or allocation_rule.effective_to>=scoped_entry.entry_date) order by allocation_rule.id loop
   insert into public.cost_center_allocations(academy_id,journal_entry_id,journal_line_id,account_id,cost_center_id,rule_id,entry_date,currency,source_amount_minor,allocated_minor,allocation_bps)
   values(scoped_entry.academy_id,scoped_entry.id,source.line_id,source.account_id,rule.cost_center_id,rule.id,scoped_entry.entry_date,scoped_entry.currency,source_amount,round(source_amount*rule.allocation_bps/10000.0)::bigint,rule.allocation_bps);inserted:=inserted+1;
  end loop;
 end loop;return inserted;
end;$$;

create function private.allocate_cost_center_on_post() returns trigger language plpgsql security invoker set search_path='' as $$begin if new.status in('posted','reversed') and old.status is distinct from new.status then perform private.refresh_cost_center_entry(new.id);end if;return new;end;$$;
create trigger allocate_cost_center_on_post after update of status on public.gl_journal_entries for each row execute function private.allocate_cost_center_on_post();

create function public.create_cost_center(target_academy_id uuid,target_code text,target_name text,target_center_type public.cost_center_type,target_linked_horse_id uuid,target_description text)
returns uuid language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());center_id uuid;begin if actor is null or not private.is_platform_administrator() then raise exception 'platform administrator access required' using errcode='42501';end if;if upper(btrim(target_code))!~'^[A-Z0-9][A-Z0-9_-]{1,19}$' or char_length(btrim(target_name)) not between 2 and 120 or (target_center_type='horse')<>(target_linked_horse_id is not null) then raise exception 'invalid cost center' using errcode='22023';end if;insert into public.cost_centers(academy_id,code,name,center_type,linked_horse_id,description,created_by)values(target_academy_id,upper(btrim(target_code)),btrim(target_name),target_center_type,target_linked_horse_id,nullif(btrim(coalesce(target_description,'')),''),actor)returning id into center_id;perform public.write_audit_event(target_academy_id,'cost_center.created','cost_center',center_id,jsonb_build_object('code',upper(btrim(target_code)),'type',target_center_type));return center_id;end;$$;

create function public.set_cost_center_status(target_cost_center_id uuid,target_active boolean) returns boolean language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());scoped public.cost_centers%rowtype;entry record;begin if actor is null or not private.is_platform_administrator() then raise exception 'platform administrator access required' using errcode='42501';end if;select * into scoped from public.cost_centers where id=target_cost_center_id for update;if not found then raise exception 'cost center not found' using errcode='P0002';end if;update public.cost_centers set active=target_active where id=scoped.id;for entry in select distinct journal_entry_id id from public.cost_center_allocations where cost_center_id=scoped.id loop perform private.refresh_cost_center_entry(entry.id);end loop;perform public.write_audit_event(scoped.academy_id,'cost_center.status_changed','cost_center',scoped.id,jsonb_build_object('active',target_active));return true;end;$$;

create function public.save_cost_center_allocation_rule(target_account_id uuid,target_cost_center_id uuid,target_allocation_bps integer,target_effective_from date,target_effective_to date,target_note text)
returns uuid language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());account_row public.gl_accounts%rowtype;center_row public.cost_centers%rowtype;rule_id uuid;overlap_total integer;entry record;begin if actor is null or not private.is_platform_administrator() then raise exception 'platform administrator access required' using errcode='42501';end if;select * into account_row from public.gl_accounts where id=target_account_id;select * into center_row from public.cost_centers where id=target_cost_center_id;if account_row.id is null or center_row.id is null or account_row.academy_id<>center_row.academy_id or account_row.category not in('revenue','expense') or target_allocation_bps not between 1 and 10000 or target_effective_to<target_effective_from then raise exception 'invalid allocation rule' using errcode='22023';end if;
 select coalesce(sum(allocation_bps),0) into overlap_total from public.cost_center_allocation_rules where account_id=target_account_id and not(cost_center_id=target_cost_center_id and effective_from=target_effective_from) and daterange(effective_from,coalesce(effective_to,'infinity'::date),'[]')&&daterange(target_effective_from,coalesce(target_effective_to,'infinity'::date),'[]');if overlap_total+target_allocation_bps>10000 then raise exception 'allocation rules exceed one hundred percent' using errcode='23514';end if;
 insert into public.cost_center_allocation_rules(academy_id,account_id,cost_center_id,allocation_bps,effective_from,effective_to,note,created_by,updated_by)values(account_row.academy_id,account_row.id,center_row.id,target_allocation_bps,target_effective_from,target_effective_to,nullif(btrim(coalesce(target_note,'')),''),actor,actor)on conflict(account_id,cost_center_id,effective_from)do update set allocation_bps=excluded.allocation_bps,effective_to=excluded.effective_to,note=excluded.note,updated_by=actor,updated_at=now()returning id into rule_id;
 for entry in select id from public.gl_journal_entries where academy_id=account_row.academy_id and status in('posted','reversed') and entry_date>=target_effective_from and(target_effective_to is null or entry_date<=target_effective_to) loop perform private.refresh_cost_center_entry(entry.id);end loop;
 perform public.write_audit_event(account_row.academy_id,'cost_center.rule_saved','cost_center_allocation_rule',rule_id,jsonb_build_object('account_id',account_row.id,'cost_center_id',center_row.id,'allocation_bps',target_allocation_bps,'effective_from',target_effective_from,'effective_to',target_effective_to));return rule_id;end;$$;

create function public.save_cost_center_monthly_budget(target_cost_center_id uuid,target_month_start date,target_currency text,target_revenue_budget_minor bigint,target_expense_budget_minor bigint,target_note text)
returns uuid language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());center_row public.cost_centers%rowtype;budget_id uuid;normalized_month date:=date_trunc('month',target_month_start)::date;normalized_currency text:=upper(btrim(target_currency));begin if actor is null or not private.is_platform_administrator() then raise exception 'platform administrator access required' using errcode='42501';end if;select * into center_row from public.cost_centers where id=target_cost_center_id;if not found or normalized_currency!~'^[A-Z]{3}$' or least(target_revenue_budget_minor,target_expense_budget_minor)<0 then raise exception 'invalid cost center budget' using errcode='22023';end if;if exists(select 1 from public.financial_close_periods where academy_id=center_row.academy_id and month_start=normalized_month and currency=normalized_currency and status='closed')then raise exception 'financial period is closed' using errcode='23514';end if;insert into public.cost_center_monthly_budgets(academy_id,cost_center_id,month_start,currency,revenue_budget_minor,expense_budget_minor,note,created_by,updated_by)values(center_row.academy_id,center_row.id,normalized_month,normalized_currency,target_revenue_budget_minor,target_expense_budget_minor,nullif(btrim(coalesce(target_note,'')),''),actor,actor)on conflict(cost_center_id,month_start,currency)do update set revenue_budget_minor=excluded.revenue_budget_minor,expense_budget_minor=excluded.expense_budget_minor,note=excluded.note,updated_by=actor,updated_at=now()returning id into budget_id;perform public.write_audit_event(center_row.academy_id,'cost_center.budget_saved','cost_center_monthly_budget',budget_id,jsonb_build_object('cost_center_id',center_row.id,'month_start',normalized_month,'currency',normalized_currency));return budget_id;end;$$;

create function public.assign_purchase_order_cost_center(target_purchase_order_id uuid,target_cost_center_id uuid) returns boolean language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());scoped_order public.purchase_orders%rowtype;scoped_center public.cost_centers%rowtype;begin if actor is null or not private.is_platform_administrator() then raise exception 'platform administrator access required' using errcode='42501';end if;select * into scoped_order from public.purchase_orders where id=target_purchase_order_id for update;select * into scoped_center from public.cost_centers where id=target_cost_center_id;if scoped_order.id is null or scoped_center.id is null or scoped_order.academy_id<>scoped_center.academy_id or not scoped_center.active then raise exception 'purchase order cost center scope is invalid' using errcode='23514';end if;update public.purchase_orders set cost_center_id=scoped_center.id,updated_by=actor,updated_at=now()where id=scoped_order.id;perform public.write_audit_event(scoped_order.academy_id,'cost_center.purchase_order_assigned','purchase_order',scoped_order.id,jsonb_build_object('cost_center_id',scoped_center.id,'amount_minor',scoped_order.amount_minor,'status',scoped_order.status));return true;end;$$;

create function public.refresh_cost_center_allocations(target_academy_id uuid,target_starts_on date,target_ends_on date,target_currency text) returns integer language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());entry record;processed integer:=0;begin if actor is null or not private.is_platform_administrator() then raise exception 'platform administrator access required' using errcode='42501';end if;if target_ends_on<target_starts_on or target_ends_on-target_starts_on>731 or upper(btrim(target_currency))!~'^[A-Z]{3}$' then raise exception 'invalid allocation range' using errcode='22023';end if;for entry in select id from public.gl_journal_entries where academy_id=target_academy_id and currency=upper(btrim(target_currency))and status in('posted','reversed')and entry_date between target_starts_on and target_ends_on loop processed:=processed+private.refresh_cost_center_entry(entry.id);end loop;return processed;end;$$;

create function public.get_cost_center_profitability(target_academy_id uuid,target_starts_on date,target_ends_on date,target_currency text)returns jsonb language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());normalized_currency text:=upper(btrim(target_currency));result jsonb;begin if actor is null or not private.is_platform_administrator() then raise exception 'platform administrator access required' using errcode='42501';end if;if target_ends_on<target_starts_on or target_ends_on-target_starts_on>731 or normalized_currency!~'^[A-Z]{3}$' then raise exception 'invalid profitability range' using errcode='22023';end if;perform public.refresh_cost_center_allocations(target_academy_id,target_starts_on,target_ends_on,normalized_currency);
 with center_actuals as(select center.id,coalesce(sum(allocation.allocated_minor)filter(where account.category='revenue'),0)::bigint revenue_actual_minor,coalesce(sum(allocation.allocated_minor)filter(where account.category='expense'),0)::bigint expense_actual_minor from public.cost_centers center left join public.cost_center_allocations allocation on allocation.cost_center_id=center.id and allocation.currency=normalized_currency and allocation.entry_date between target_starts_on and target_ends_on left join public.gl_accounts account on account.id=allocation.account_id where center.academy_id=target_academy_id group by center.id),center_budgets as(select center.id,coalesce(sum(budget.revenue_budget_minor),0)::bigint revenue_budget_minor,coalesce(sum(budget.expense_budget_minor),0)::bigint expense_budget_minor from public.cost_centers center left join public.cost_center_monthly_budgets budget on budget.cost_center_id=center.id and budget.currency=normalized_currency and budget.month_start between date_trunc('month',target_starts_on)::date and date_trunc('month',target_ends_on)::date where center.academy_id=target_academy_id group by center.id),center_commitments as(select center.id,coalesce(sum(purchase_order.amount_minor)filter(where purchase_order.status in('approved','partially_received')),0)::bigint committed_minor from public.cost_centers center left join public.purchase_orders purchase_order on purchase_order.cost_center_id=center.id and purchase_order.currency=normalized_currency and coalesce(purchase_order.expected_on,purchase_order.approved_at::date)between target_starts_on and target_ends_on where center.academy_id=target_academy_id group by center.id),rows as(select center.id,center.code,center.name,center.center_type,center.active,actual.revenue_actual_minor,actual.expense_actual_minor,budget.revenue_budget_minor,budget.expense_budget_minor,commitment.committed_minor,actual.revenue_actual_minor-actual.expense_actual_minor contribution_minor,(actual.revenue_actual_minor-actual.expense_actual_minor)-(budget.revenue_budget_minor-budget.expense_budget_minor) budget_variance_minor from public.cost_centers center join center_actuals actual on actual.id=center.id join center_budgets budget on budget.id=center.id join center_commitments commitment on commitment.id=center.id where center.academy_id=target_academy_id),source_totals as(select coalesce(sum(case when account.category='revenue' then case when account.normal_balance='credit' then line.credit_minor-line.debit_minor else line.debit_minor-line.credit_minor end else 0 end),0)::bigint revenue_minor,coalesce(sum(case when account.category='expense' then case when account.normal_balance='debit' then line.debit_minor-line.credit_minor else line.credit_minor-line.debit_minor end else 0 end),0)::bigint expense_minor from public.gl_journal_entries entry join public.gl_journal_lines line on line.journal_entry_id=entry.id join public.gl_accounts account on account.id=line.account_id where entry.academy_id=target_academy_id and entry.currency=normalized_currency and entry.status in('posted','reversed')and entry.entry_date between target_starts_on and target_ends_on and account.category in('revenue','expense'))
 select jsonb_build_object('starts_on',target_starts_on,'ends_on',target_ends_on,'currency',normalized_currency,'totals',jsonb_build_object('revenue_actual_minor',coalesce((select sum(revenue_actual_minor)from rows),0),'expense_actual_minor',coalesce((select sum(expense_actual_minor)from rows),0),'contribution_minor',coalesce((select sum(contribution_minor)from rows),0),'committed_minor',coalesce((select sum(committed_minor)from rows),0),'revenue_budget_minor',coalesce((select sum(revenue_budget_minor)from rows),0),'expense_budget_minor',coalesce((select sum(expense_budget_minor)from rows),0),'unallocated_revenue_minor',(select revenue_minor from source_totals)-coalesce((select sum(revenue_actual_minor)from rows),0),'unallocated_expense_minor',(select expense_minor from source_totals)-coalesce((select sum(expense_actual_minor)from rows),0)),'centers',coalesce((select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'center_type',center_type,'active',active,'revenue_actual_minor',revenue_actual_minor,'expense_actual_minor',expense_actual_minor,'contribution_minor',contribution_minor,'committed_minor',committed_minor,'revenue_budget_minor',revenue_budget_minor,'expense_budget_minor',expense_budget_minor,'budget_variance_minor',budget_variance_minor)order by contribution_minor desc,code)from rows),'[]'::jsonb))into result;return result;end;$$;

